-- SecureBank Ledger Service - one-time database bootstrap (run by a MySQL administrator).
--
-- 1. Replace BOTH password placeholders below with strong secrets generated by you.
--    Never commit real passwords, never put them in application.yml, and never ship them in a ZIP.
-- 2. Run:  mysql -u <admin-user> -p < 01-create-database-and-users.sql
-- 3. This script only touches the securebank_ledger schema and the two ledger_* users.
--    It never drops anything and never touches other services' databases.
--
-- Host '127.0.0.1' keeps the accounts local-only. Change it deliberately if the service runs elsewhere.

CREATE DATABASE IF NOT EXISTS securebank_ledger
    CHARACTER SET utf8mb4
    COLLATE utf8mb4_0900_ai_ci;

-- Migration account: used ONLY by Flyway (LEDGER_DB_MIGRATION_USERNAME / _PASSWORD) to create and alter
-- tables. It has DDL rights but is never used by the running request-handling code paths.
CREATE USER IF NOT EXISTS 'ledger_migrator'@'127.0.0.1' IDENTIFIED BY '<CHANGE_ME_MIGRATOR_PASSWORD>';
GRANT CREATE, ALTER, INDEX, REFERENCES, SELECT, INSERT, UPDATE, DELETE
    ON securebank_ledger.* TO 'ledger_migrator'@'127.0.0.1';
-- (UPDATE/DELETE are needed by Flyway for its own flyway_schema_history table only.)

-- Application account: used by the running service (LEDGER_DB_USERNAME / _PASSWORD).
-- SELECT + INSERT only: no DDL, and no UPDATE/DELETE, so posted entries cannot be altered or removed
-- even if the application were compromised. Corrections are reversal entries (new rows).
CREATE USER IF NOT EXISTS 'ledger_app'@'127.0.0.1' IDENTIFIED BY '<CHANGE_ME_APP_PASSWORD>';
GRANT SELECT, INSERT ON securebank_ledger.* TO 'ledger_app'@'127.0.0.1';

FLUSH PRIVILEGES;
